export const getReleaseAssetUploadResponseSchema = defineSchema((v) => v.object({
    stored: v.boolean(),
    existed: v.boolean(),
}));
export const getDependencyArtifactAssetUploadResponseSchema = defineSchema((v) => v.object({
    stored: v.literal(true),
    existed: v.boolean(),
}));
export const getDependencyArtifactBuildResultResponseSchema = defineSchema((v) => v.object({
    accepted: v.literal(true),
    state: v.enum(["ready", "failed"]),
}));
export const getReleaseAssetManifestStateResponseSchema = defineSchema((v) => v.object({
    state: v.enum([
        "queued",
        "building",
        "partial",
        "ready",
        "failed",
        "superseded",
    ]),
    manifest_version: v.number().optional(),
}));
export const getReleaseAssetManifestResponseSchema = defineSchema((v) => v.object({
    state: v.enum([
        "queued",
        "building",
        "partial",
        "ready",
        "failed",
        "superseded",
    ]),
    manifest_version: v.number(),
    manifest: v.union([v.record(v.string(), v.unknown()), v.null()]),
}));
/**
 * Project schema extended with the `environments` array — used by the
 * domain-lookup endpoint which returns a project plus its environments.
 *
 * Lifted out of `operations.ts` so the inline `extend()` no longer needs to
 * import the SchemaValidator at the callsite.
 */
export const getProjectWithEnvironmentsSchema = defineSchema((v) => getProjectSchema().extend({
    environments: v
        .array(v.object({
        id: v.string().uuid(),
        name: v.string(),
        domains: v.array(v.string()).optional(),
        active_release_id: v.string().uuid().nullable().optional(),
    }))
        .optional(),
}));
